/**
 * ItemStatistic seed data (SRS M08 v1.11 §6.8.1 DATA-M08-11; M18 §6.11 H). OBSERVED: the question stems,
 * subjects, topics, the correct answer and the most-chosen wrong answer (with its count) of the KLUANG /
 * 8880 lists (snapshot 2026-09-26), the pupil counts, and the 8765 cards (top-up). Generated by
 * `scratchpad/m08-t1/gen-items2.cjs` from docs/discovery/inventory/M18; person tokens are replaced by
 * pupil references (`t{n}` = the n-th observed 8880 person token, resolved to an M02 pupil of 8880 in
 * finalise; `a{n}` = the n-th answering pupil of school 8765). INFERRED (not observed): which letter each
 * non-popular wrong pupil chose; the kohesi question's options and pupils; the 8765 attempts, wrong counts and
 * option letters; the T5 variant of 8765 (attempts 4, wrong 2). Question ids 701001+ are the M18 block (XL3-11).
 */

export interface CriticalQuestion {
  id: number
  stem: string
  subjectName: string
  topic: string
  subtopic: string
  /** Letter of the correct option (OBSERVED where the list shows it; INFERRED "A" otherwise). */
  correct: 'A' | 'B' | 'C' | 'D'
  /** The option texts the snapshot shows (correct and most-chosen wrong option). */
  known: Partial<Record<'A' | 'B' | 'C' | 'D', string>>
}

export interface ItemSeedRow {
  q: number
  attempts: number
  pupils: number
  wrong: number
  pop: 'A' | 'B' | 'C' | 'D' | null
  popN: number
  /** [pupil reference, wrong option letter] */
  wp: readonly (readonly [string, 'A' | 'B' | 'C' | 'D'])[]
}

export interface ItemSeedSet {
  scopeKind: 'ppd' | 'state' | 'school'
  scopeId: string | number
  tingkatan: 'T4' | 'T5' | null
  rows: readonly ItemSeedRow[]
}

